#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeProject: FfiConverter {
    typealias FfiType = UInt64
    typealias SwiftType = Project

    public static func lift(_ handle: UInt64) throws -> Project {
        return Project(unsafeFromHandle: handle)
    }

    public static func lower(_ value: Project) -> UInt64 {
        return value.uniffiCloneHandle()
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> Project {
        let handle: UInt64 = try readInt(&buf)
        return try lift(handle)
    }

    public static func write(_ value: Project, into buf: inout [UInt8]) {
        writeInt(&buf, lower(value))
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeProject_lift(_ handle: UInt64) throws -> Project {
    return try FfiConverterTypeProject.lift(handle)
}

